namespace ghidra.app.plugin.core.debug.gui.breakpoint.timeline;



using ghidra.app.plugin;
using ghidra.app.plugin.core.debug;
using ghidra.app.plugin.core.debug;
using ghidra.app.plugin.core.debug.@event;
using ghidra.app.plugin.core.debug.@event;
using ghidra.app.services;
using ghidra.app.services;
using ghidra.framework.plugintool;
using ghidra.framework.plugintool.util;
using ghidra.trace.model;

/* @PluginInfo(
	shortDescription = "Debugger breakpoint hit timeline",
	description = "Timeline of all snapshots showing breakpoint hits",
	category = PluginCategoryNames.DEBUGGER,
	packageName = DebuggerPluginPackage.NAME,
	status = PluginStatus.UNSTABLE,
	servicesRequired = { typeof(DebuggerTraceManagerService), typeof(DebuggerStaticMappingService) },
	eventsConsumed = { typeof(TraceClosedPluginEvent), typeof(TraceActivatedPluginEvent), }
) */
public class BreakpointTimelinePlugin : AbstractDebuggerPlugin {
	BreakpointTimelineProvider provider;
	BreakpointTimelineActions actions;

	private Trace currentTrace;

	private Map<Trace, List<BreakpointTimelineProvider>> traceSpecificZoomProviders =
		new();

	public BreakpointTimelinePlugin(PluginTool tool) : base(tool)
    {
	}

	void createZoomProvider(string title, long start, long stop) {
		traceSpecificZoomProviders.computeIfAbsent(currentTrace, k => new())
				.add(new BreakpointTimelineProvider(provider, title, start, stop));
	}

	/* @Override */
	protected void dispose() {
		actions.dispose();
		foreach (var providers in traceSpecificZoomProviders.values()) {
			foreach (var provider in providers) {
				tool.removeComponentProvider(provider);
			}
		}
		tool.removeComponentProvider(provider);
		base.dispose();
	}

	private void hideZoomProviders(Trace t) {
		List<BreakpointTimelineProvider> zoomProviders = traceSpecificZoomProviders.get(t);
		if (zoomProviders != null) {
			foreach (BreakpointTimelineProvider p in zoomProviders) {
				tool.showComponentProvider(p, false);
			}
		}
	}

	/* @Override */
	protected void init() {
		base.init();
		provider = new BreakpointTimelineProvider(this);
		actions = new BreakpointTimelineActions(getTool());
	}

	/* @Override */
	public void processEvent(PluginEvent @event) {
		base.processEvent(@event);
		switch (@event) {
			case TraceClosedPluginEvent evt: {
				Trace t = evt.getTrace();

				if (currentTrace == t) {
					currentTrace = null;
					provider.setTrace(null);
					actions.setTrace(null);
				}
				removeZoomProviders(t);
			}
			case TraceActivatedPluginEvent evt: {
				Trace t = evt.getActiveCoordinates().getTrace();
				if (t == null) {
					provider.setTrace(null);
				}
				else if (currentTrace != t) {
					hideZoomProviders(currentTrace);
					currentTrace = t;
					provider.setTrace(currentTrace);
					showZoomProviders(currentTrace);
				}
				else {
					refreshAllProviders(null);
				}
				actions.setTrace(t);
			}
			default: {
			}
		}
	}

	void refreshAllProviders(BreakpointTimelineProvider currentProvider) {
		List<BreakpointTimelineProvider> zoomProviders =
			traceSpecificZoomProviders.get(currentTrace);
		if (zoomProviders != null) {
			foreach (BreakpointTimelineProvider p in zoomProviders) {
				if (p != currentProvider) {
					p.refresh();
				}
			}
		}

		if (provider != currentProvider) {
			provider.refresh();
		}
	}

	void removeZoomProviders(Trace t) {
		List<BreakpointTimelineProvider> zoomProviders = traceSpecificZoomProviders.remove(t);
		if (zoomProviders != null) {
			foreach (BreakpointTimelineProvider p in zoomProviders) {
				tool.removeComponentProvider(p);
			}
		}
	}

	private void showZoomProviders(Trace t) {
		List<BreakpointTimelineProvider> zoomProviders = traceSpecificZoomProviders.get(t);
		if (zoomProviders != null) {
			foreach (BreakpointTimelineProvider p in zoomProviders) {
				tool.showComponentProvider(p, true);
			}
		}
	}
}
